/**
 * A helper type which removes properties that may only be undefined from an
 * object type `T`.
 */
export type OmitUndefinedValues<T> = T extends infer U ? {
    [K in keyof U as [U[K]] extends [undefined] ? never : K]: U[K];
} : never;
